package com.taller.portal.config;
import com.taller.portal.service.VpicImportService; import java.nio.file.Path; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.ConfigurableApplicationContext; import org.springframework.stereotype.Component;
/** Ejecuta descarga opcional/importación vPIC desde script y termina sin iniciar la API normal. */
@Component @ConditionalOnProperty(name="app.vpic.import-file") public class VpicImportRunner implements ApplicationRunner { private final VpicImportService servicio; private final ConfigurableApplicationContext contexto; /** @param servicio importador local @param contexto proceso a cerrar. */ public VpicImportRunner(VpicImportService servicio,ConfigurableApplicationContext contexto){this.servicio=servicio;this.contexto=contexto;} /** @param argumentos argumentos Spring. @throws Exception ante archivo o red inválidos. */ @Override public void run(ApplicationArguments argumentos)throws Exception{Path archivo=Path.of(contexto.getEnvironment().getProperty("app.vpic.import-file"));if(Boolean.parseBoolean(contexto.getEnvironment().getProperty("app.vpic.download","false")))servicio.descargar(archivo);var resultado=servicio.importar(archivo);System.out.printf("vPIC: marcas nuevas %d/existentes %d, modelos nuevos %d/existentes %d, omitidos %d, total marcas %d, total modelos %d.%n",resultado.marcasNuevas(),resultado.marcasExistentes(),resultado.modelosNuevos(),resultado.modelosExistentes(),resultado.omitidos(),resultado.totalMarcas(),resultado.totalModelos());System.out.print(servicio.cobertura());System.exit(SpringApplication.exit(contexto));} }
